def transform(grid):
    # Uniform full-width rows and full-height columns separate the panels.
    h, w = len(grid), len(grid[0])
    sep_rows = {r for r in range(h) if len(set(grid[r])) == 1}
    sep_cols = {c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1}
    row_groups, col_groups = [], []
    cur = []
    for r in range(h):
        if r in sep_rows:
            if cur:
                row_groups.append(cur)
                cur = []
        else:
            cur.append(r)
    if cur:
        row_groups.append(cur)
    cur = []
    for c in range(w):
        if c in sep_cols:
            if cur:
                col_groups.append(cur)
                cur = []
        else:
            cur.append(c)
    if cur:
        col_groups.append(cur)
    cells = [grid[r][c] for r in range(h) if r not in sep_rows for c in range(w) if c not in sep_cols]
    bg = max(set(cells), key=cells.count)
    out = []
    for rows in row_groups:
        outrow = []
        for cols in col_groups:
            marks = sum(grid[r][c] != bg for r in rows for c in cols)
            outrow.append(1 if marks == 2 else bg)
        out.append(outrow)
    return out
